suppressPackageStartupMessages({library(rhdf5);library(Matrix);library(data.table);library(arrow)})
root='/external/GBM_SOURCE_ROOT/GBM标签数据库/GBM_unified_registry_de_novo_benchmark_AuthorityV2_2026-07-23'; out=file.path(root,'09_de_novo_derived/13_single_cell_v2_1_1'); dest=file.path(out,'03_pseudobulk_scores/full_gene_pseudobulk_v2_1_2');dir.create(dest,recursive=TRUE,showWarnings=FALSE)
h5='/external/GBMAP/GBmap_core_861acfd8.h5ad';old='/external/GBM_SOURCE_ROOT/04_single_cell'
catcol=function(n){ca=h5read(h5,paste0('/obs/',n,'/categories'));co=h5read(h5,paste0('/obs/',n,'/codes'));z=rep('',length(co));z[co>=0]=ca[co[co>=0]+1];z}; varcol=function(n){ca=h5read(h5,paste0('/raw/var/',n,'/categories'));co=h5read(h5,paste0('/raw/var/',n,'/codes'));z=rep('',length(co));z[co>=0]=ca[co[co>=0]+1];z}
feature=toupper(varcol('feature_name')); author=catcol('author');donor=catcol('donor_id');assay=catcol('assay');l1=catcol('annotation_level_1');l2=catcol('annotation_level_2');l3=catcol('annotation_level_3');l4=catcol('annotation_level_4')
man=rbindlist(list(fread(file.path(old,'03_gse131928/patient_compartment_manifest.tsv')),fread(file.path(old,'04_external_validation/external_patient_compartment_manifest.tsv'))));man=man[eligible_main==TRUE & compartment!='whole_tumor'];target=Sys.getenv('DATASET_ID','');if(nzchar(target))man=man[dataset==target];setorder(man,dataset,platform,patient_id,compartment,state_label)
ptr=as.numeric(h5read(h5,'/raw/X/indptr')); readx=function(ii){ii=sort(ii); cuts=c(which(diff(ii)>1),length(ii)); starts=c(1,head(cuts,-1)+1);bl=lapply(seq_along(starts),function(k){r=ii[starts[k]:cuts[k]];p=ptr[(r[1]+1):(r[length(r)]+2)];lo=p[1]+1;hi=p[length(p)];sparseMatrix(i=rep(seq_along(r),diff(p)),j=as.numeric(h5read(h5,'/raw/X/indices',index=list(lo:hi)))+1,x=as.numeric(h5read(h5,'/raw/X/data',index=list(lo:hi))),dims=c(length(r),length(feature)))});do.call(rbind,bl)}
broad=function(i)ifelse(l1[i]=='Neoplastic','malignant',ifelse(l2[i]=='Myeloid','myeloid',ifelse(l2[i]=='Vascular','endothelial_pericyte',ifelse(l2[i]=='Lymphoid','lymphoid','other_nonmalignant'))))
rows=list();cache=list();for(k in seq_len(nrow(man))){r=man[k]; key=paste(r$dataset,r$platform,r$patient_id,sep='|');if(is.null(cache[[key]])){mask=if(r$dataset=='GSE131928') author=='Neftel2019' & assay==r$platform else author==r$dataset;ii=which(mask&donor==r$patient_id)-1; x=readx(ii); cache[[key]]=list(x=x,lib=Matrix::rowSums(x),b=broad(ii+1),i=ii)};q=cache[[key]];cp=as.character(r$compartment); take=if(cp=='malignant')which(q$b=='malignant') else if(cp=='nonmalignant')which(q$b!='malignant') else if(cp=='myeloid')which(q$b=='myeloid') else if(cp=='lymphoid')which(q$b=='lymphoid') else if(cp=='endothelial_pericyte')which(q$b=='endothelial_pericyte') else if(cp=='other_nonmalignant')which(q$b=='other_nonmalignant') else if(cp=='malignant_state_AC-like')which(q$b=='malignant'&l3[q$i+1]=='AC-like') else if(cp=='malignant_state_MES-like')which(q$b=='malignant'&l3[q$i+1]=='MES-like') else if(cp=='malignant_state_OPC-like')which(q$b=='malignant'&l3[q$i+1]=='OPC-like') else if(cp=='malignant_state_NPC-like')which(q$b=='malignant'&l3[q$i+1]=='NPC-like') else which(q$b=='malignant'&grepl('Prolif',l4[q$i+1]));cnt=Matrix::colSums(q$x[take,,drop=FALSE]); vals=as.list(log2((cnt+.5)/(sum(q$lib[take])+1)*1e6));names(vals)=feature;rows[[k]]=cbind(r,as.data.table(vals));if(k%%50==0)cat(k,'\n')}
pb=rbindlist(rows,fill=TRUE);tag=if(nzchar(target))target else 'ALL';write_parquet(as.data.frame(pb),file.path(dest,paste0(tag,'_full_gene_pseudobulk.parquet')));fwrite(data.table(dataset=unique(pb$dataset),feature_n=length(feature),pseudobulk_n=nrow(pb),layer='raw/X counts',status='PASS'),file.path(dest,paste0(tag,'_FULL_GENE_PSEUDOBULK_MANIFEST.tsv')),sep='\t')
